INSERT INTO products (product_id, category_id, subcategory_id, image_path, product_name, manufacturer, description, composition, price) VALUES (29, 3, 9, 'IMG_MB_174349.png', 'Ботинки мужские демисезонные', 'Барбари', 'Ботинки из натуральной кожи темно-коричневого и черного цвета на шнурках. Производитель: Дом обуви «Берестов», г. Москва', 'Верх — натуральная кожа, подкладка — текстиль, подошва — искусственный материал', 21500);
INSERT INTO products (product_id, category_id, subcategory_id, image_path, product_name, manufacturer, description, composition, price) VALUES (30, 3, 9, 'IMG_MB_191200.png', 'Ботинки черные из натуральной кожи', 'Кожевенные традиции', 'Ботинки представляют баланс традиций и современности. Выполнены из натуральной кожи насыщенного черного цвета. Производитель: ЗАО «Кожевенные традиции», г. Вятка', 'Верх — натуральная кожа, подкладка — ворсин, стелька — ворсин, подошва — тунит', 14567);
INSERT INTO products (product_id, category_id, subcategory_id, image_path, product_name, manufacturer, description, composition, price) VALUES (31, 3, 9, 'IMG_MB_191205.png', 'Ботинки зимние классические', 'Барбари', 'Выбор на каждый день — натуральная кожа, натуральный мех. Производитель: Дом обуви «Барбари», г. Новороссийск', 'Верх — натуральная кожа, подкладка — натуральный мех, стелька — натуральный мех, подошва — ТЭП', 15670);
